import{_ as n,C as r,o as e,c as s,a2 as a,b as l,w as o,a as d,E as c,a3 as p}from"./chunks/framework.Brv5O9VI.js";const y=JSON.parse('{"title":"14.3 Networking & Communication Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.3-networking-and-communication.md","filePath":"system-design/14.3-networking-and-communication.md"}'),g={name:"system-design/14.3-networking-and-communication.md"};function h(u,t,m,T,f,P){const i=r("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="_14-3-networking-communication-protocols" tabindex="-1">14.3 Networking &amp; Communication Protocols <a class="header-anchor" href="#_14-3-networking-communication-protocols" aria-label="Permalink to &quot;14.3 Networking &amp; Communication Protocols&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Networking and communication protocols govern how data moves between clients and servers across physical networks—covering transport layers (TCP/UDP), application standards (HTTP/1.1 vs HTTP/2 vs gRPC), and message serialization formats (JSON, Protobuf, CSV).</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Application Protocol</strong>: HTTP/1.1 over TCP via Uvicorn ([<code>Dockerfile:L15</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/Dockerfile#L15)).</li><li><strong>Data Serialization</strong>: <ul><li><code>POST /chat</code>: JSON request and response payloads validated via Pydantic ([<code>app.py:L61,L74</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L61)).</li><li><code>POST /audit/export</code>: <code>text/csv</code> stream with <code>Content-Disposition</code> attachment header ([<code>app.py:L148-L151</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L148-L151)).</li></ul></li><li><strong>CORS Handling</strong>: Permissive wildcard <code>allow_origins=[&quot;*&quot;]</code> configured via <code>CORSMiddleware</code> ([<code>app.py:L18</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L18)).</li></ul>',6)),(e(),l(p,null,{default:o(()=>[c(i,{id:"mermaid-42",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Browser%20as%20Browser%20Client%20(React%2019)%0A%20%20%20%20participant%20TCP%20as%20TCP%20Handshake%20(3-Way)%0A%20%20%20%20participant%20TLS%20as%20TLS%201.3%20Handshake%20(Proxy)%0A%20%20%20%20participant%20HTTP%20as%20HTTP%2F1.1%20Pipe%0A%20%20%20%20participant%20Server%20as%20Uvicorn%20(app.py)%0A%0A%20%20%20%20Browser-%3E%3ETCP%3A%20SYN%0A%20%20%20%20TCP--%3E%3EBrowser%3A%20SYN-ACK%0A%20%20%20%20Browser-%3E%3ETCP%3A%20ACK%20(Connection%20Established)%0A%20%20%20%20Browser-%3E%3ETLS%3A%20ClientHello%0A%20%20%20%20TLS--%3E%3EBrowser%3A%20ServerHello%20%26%20Certs%0A%20%20%20%20Browser-%3E%3EHTTP%3A%20POST%20%2Fchat%20(Keep-Alive)%0A%20%20%20%20HTTP-%3E%3EServer%3A%20Route%20payload%20to%20FastAPI%0A%20%20%20%20Server--%3E%3EHTTP%3A%20200%20OK%20(Content-Type%3A%20application%2Fjson)%0A%20%20%20%20HTTP--%3E%3EBrowser%3A%20JSON%20Audit%20Pack%20Payload%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_3-comparison-with-alternatives" tabindex="-1">3. Comparison with Alternatives <a class="header-anchor" href="#_3-comparison-with-alternatives" aria-label="Permalink to &quot;3. Comparison with Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Protocol</th><th style="text-align:left;">Transport</th><th style="text-align:left;">Multiplexing</th><th style="text-align:left;">Payload Format</th><th style="text-align:left;">Streaming Support</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>REST over HTTP/1.1</strong> (Used)</td><td style="text-align:left;">TCP</td><td style="text-align:left;">Head-of-Line Blocking</td><td style="text-align:left;">JSON / CSV Text</td><td style="text-align:left;">Chunked Transfer</td><td style="text-align:left;"><strong>Optimal (Universal browser client support)</strong></td></tr><tr><td style="text-align:left;"><strong>HTTP/2</strong></td><td style="text-align:left;">TCP</td><td style="text-align:left;">Binary Multiplexing</td><td style="text-align:left;">JSON / Binary</td><td style="text-align:left;">Native Streams</td><td style="text-align:left;">Recommended for production proxy</td></tr><tr><td style="text-align:left;"><strong>gRPC</strong></td><td style="text-align:left;">HTTP/2</td><td style="text-align:left;">High Multiplexing</td><td style="text-align:left;">Protocol Buffers</td><td style="text-align:left;">Bi-directional</td><td style="text-align:left;">Overkill for browser clients</td></tr><tr><td style="text-align:left;"><strong>WebSockets</strong></td><td style="text-align:left;">TCP (Upgraded)</td><td style="text-align:left;">Full Duplex</td><td style="text-align:left;">Text / Binary Frames</td><td style="text-align:left;">Continuous</td><td style="text-align:left;">Not needed (No streaming chat)</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>HTTP/1.1 Head-of-Line Blocking</strong>: Sequential requests over a single TCP connection must wait for preceding requests to finish, causing minor latency queuing during rapid parallel burst queries.</li><li><strong>JSON Text Overhead</strong>: JSON serialization incurs ~15% higher byte size compared to binary formats like Protocol Buffers or MessagePack.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Standard TCP connection reuse via HTTP Keep-Alive handles the load without packet drops.</li><li><strong>At 100x Load</strong>: TCP socket exhaustion (TIME_WAIT saturation) can occur if clients open and close connections rapidly rather than reusing connections.</li><li><strong>At 1000x Load</strong>: HTTP/1.1 connection limits throttle throughput; requires an HTTP/2 or HTTP/3 reverse proxy (Nginx or Cloudflare) to multiplex thousands of streams over single TCP/QUIC connections.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Place the backend behind an <strong>Nginx reverse proxy</strong> terminating <strong>HTTP/2 with TLS 1.3</strong>, enabling single-connection multiplexing, gzip/Brotli payload compression, and strict CORS origin headers.</p><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We use standard REST over HTTP/1.1 with JSON payloads and CSV streaming because it provides universal, zero-friction compatibility with browser clients and ERP export systems. For production scale, placing the service behind an Nginx proxy terminating HTTP/2 provides binary multiplexing and connection reuse with zero application code changes.&quot;</p></blockquote>',15))])}const w=n(g,[["render",h]]);export{y as __pageData,w as default};
